//! Read-only bounded JMAP header sync over host-managed OAuth HTTPS.
use crate::*;
const CORE:&str="urn:ietf:params:jmap:core";const MAIL:&str="urn:ietf:params:jmap:mail";
#[derive(Clone)]pub struct Mailbox{pub endpoint:String,pub account:String,pub mailbox:String,pub credential:String}
fn id(s:&str)->Result<(),String>{if s.is_empty()||s.len()>256||!s.bytes().all(|b|(33..=126).contains(&b)){Err("Invalid mail identifier".into())}else{Ok(())}}
impl Mailbox{
 pub fn new(endpoint:&str,account:&str,mailbox:&str,credential:&str)->Result<Self,String>{let host=endpoint.strip_prefix("https://").ok_or("Configure an HTTPS JMAP endpoint")?.split('/').next().unwrap_or("");if endpoint.len()>512||endpoint.chars().any(|c|c.is_control()||c.is_whitespace()||"@?#\\".contains(c))||!host.contains('.')||host.split('.').any(|p|p.is_empty()||!p.bytes().all(|b|b.is_ascii_alphanumeric()||b==b'-')){return Err("Invalid fixed JMAP endpoint".into())}for s in[account,mailbox,credential]{id(s)?}Ok(Self{endpoint:endpoint.into(),account:account.into(),mailbox:mailbox.into(),credential:credential.into()})}
 fn binding(&self)->Value{json!({"endpoint":self.endpoint,"account":self.account,"mailbox":self.mailbox,"credential":self.credential})}
}
/// Explicit provider connection uses the host vault; never accept a token/password here.
pub fn connect(provider:&str,then:&str)->Value{accounts::connect(provider,then)}
pub fn request(m:&Mailbox,position:u32,then:&str)->Result<Value,String>{Mailbox::new(&m.endpoint,&m.account,&m.mailbox,&m.credential)?;if position>=100||position%20!=0{return Err("Mail sync supports five20-header pages".into())}let data=json!({"using":[CORE,MAIL],"methodCalls":[["Email/query",{"accountId":m.account,"filter":{"inMailbox":m.mailbox},"sort":[{"property":"receivedAt","isAscending":false}],"position":position,"limit":20,"calculateTotal":false},"q"],["Email/get",{"accountId":m.account,"#ids":{"resultOf":"q","name":"Email/query","path":"/ids"},"properties":["id","subject","from","receivedAt"]},"g"]]});Ok(accounts::authenticated(http::post_json(&m.endpoint,&data,then),&m.credential))}
fn display(v:&Value,max:usize)->Result<String,String>{if v.is_null(){return Ok(String::new())}v.as_str().filter(|s|s.chars().count()<=max&&!s.chars().any(char::is_control)).map(str::to_string).ok_or("Invalid mail display metadata".into())}
/// Validate a complete correlated response before replacing any saved page.
pub fn page(m:&Mailbox,response:&Value,position:u32)->Result<Value,String>{request(m,position,"check")?;if response["status"]!=200{return Err("Mail sync failed; saved headers retained".into())}let r=http::parse_json(response)?;let methods=r["methodResponses"].as_array().filter(|a|a.len()==2).ok_or("Expected two correlated JMAP responses")?;let find=|tag:&str,name:&str|->Result<&Value,String>{let rows:Vec<_>=methods.iter().filter(|r|r[2]==tag).collect();if rows.len()!=1||rows[0][0]!=name||rows[0].as_array().is_none_or(|a|a.len()!=3){return Err("JMAP method failed or response correlation changed".into())}let v=&rows[0][1];if v["accountId"]!=m.account{return Err("JMAP account changed".into())}Ok(v)};let q=find("q","Email/query")?;let g=find("g","Email/get")?;if q["position"].as_u64()!=Some(position as u64){return Err("Mailbox position changed; refresh from the first page".into())}let state=q["queryState"].as_str().ok_or("Missing mail query state")?;id(state)?;id(g["state"].as_str().ok_or("Missing mail object state")?)?;
 let ids=q["ids"].as_array().filter(|a|a.len()<=20).ok_or("Mail page exceeds20 headers")?;let mut expected=std::collections::BTreeSet::new();for v in ids{let s=v.as_str().ok_or("Invalid email identity")?;id(s)?;if !expected.insert(s){return Err("Duplicate mail identity".into())}}
 if g["notFound"].as_array().is_none_or(|a|!a.is_empty()){return Err("Mail changed during sync; refresh explicitly".into())}let list=g["list"].as_array().filter(|a|a.len()==ids.len()).ok_or("Incomplete mail page")?;let mut rows=std::collections::BTreeMap::new();for row in list{let key=row["id"].as_str().filter(|s|expected.contains(s)).ok_or("Unexpected mail identity")?;let from=if row["from"].is_null(){vec![]}else{let a=row["from"].as_array().filter(|a|a.len()<=10).ok_or("Too many mail senders")?;let mut senders=Vec::new();for s in a{senders.push(json!({"name":display(&s["name"],120)?,"email":display(&s["email"],254)?}));}senders};let value=json!({"id":key,"subject":display(&row["subject"],240)?,"from":from,"receivedAt":display(&row["receivedAt"],40)?});if rows.insert(key,value).is_some(){return Err("Duplicate header result".into())}}
 let items:Vec<_>=ids.iter().map(|v|rows.remove(v.as_str().unwrap()).unwrap()).collect();Ok(json!({"binding":m.binding(),"position":position,"query_state":state,"object_state":g["state"],"items":items,"more":ids.len()==20&&position<80,"window_limited":ids.len()==20&&position==80}))}
/// Bounded snapshot merge. A query-state change cannot splice inconsistent pages.
pub fn merge(previous:&Value,page:&Value)->Result<Value,String>{let position=page["position"].as_u64().filter(|p|*p<100&&*p%20==0).ok_or("Invalid page position")?;let incoming=page["items"].as_array().filter(|a|a.len()<=20).ok_or("Invalid mail page")?;let mut items=if position==0{Vec::new()}else{if previous["binding"]!=page["binding"]||previous["query_state"]!=page["query_state"]{return Err("Mailbox changed; refresh without discarding saved headers".into())}let old=previous["items"].as_array().filter(|a|a.len()==position as usize).ok_or("Mail pagination gap")?;old.clone()};let mut seen=std::collections::BTreeSet::new();for r in items.iter().chain(incoming){let s=r["id"].as_str().ok_or("Missing mail identity")?;if !seen.insert(s){return Err("Duplicate across mail pages; refresh explicitly".into())}}items.extend(incoming.iter().cloned());let mut result=page.clone();result["items"]=json!(items);if result.to_string().len()>15000{return Err("Mail snapshot exceeds15KiB; saved headers retained".into())}Ok(result)}
/// Store one bounded snapshot with optimistic revision checks; conflicts are explicit.
pub fn save(snapshot:Value,revision:u64,then:&str)->Result<Value,String>{if snapshot.to_string().len()>15000||!snapshot["items"].is_array()||!snapshot["binding"].is_object(){return Err("Invalid or oversized mail snapshot".into())}Ok(collections::transact("mail_headers",revision,1,None,vec![collections::put("snapshot",snapshot)],then))}
pub fn saved(m:&Mailbox,record:&Value)->Result<Value,String>{let snapshot=&record["data"];if snapshot["binding"]!=m.binding(){return Err("Saved headers belong to another mail connection".into())}if snapshot.to_string().len()>15000{return Err("Saved headers exceed bounds".into())}Ok(snapshot.clone())}
pub fn load(then:&str)->Value{collections::get("mail_headers","snapshot",then)}
pub fn clear(revision:u64,then:&str)->Value{collections::clear("mail_headers",revision,then)}
#[cfg(test)]mod tests{use super::*;fn m()->Mailbox{Mailbox::new("https://mail.example.org/jmap","account","inbox","opaque-handle").unwrap()}fn r()->Value{json!({"status":200,"text":json!({"methodResponses":[["Email/query",{"accountId":"account","position":0,"queryState":"q1","ids":["e1"]},"q"],["Email/get",{"accountId":"account","state":"s1","notFound":[],"list":[{"id":"e1","subject":"café","from":[{"name":"Demo","email":"demo@example.org"}],"receivedAt":"2026-10-25T00:00:00Z"}]},"g"]]}).to_string()})}
#[test]fn email_transport_uses_opaque_account_and_only_header_methods(){let e=request(&m(),0,"done").unwrap();assert_eq!(e["args"]["account"],"opaque-handle");let body:Value=serde_json::from_str(e["args"]["body"].as_str().unwrap()).unwrap();assert_eq!(body["methodCalls"][1][1]["#ids"]["resultOf"],"q");assert!(!e.to_string().contains("EmailSubmission"));assert!(request(&m(),100,"done").is_err());}
#[test]fn email_headers_are_correlated_and_strip_body_fields(){let p=page(&m(),&r(),0).unwrap();assert_eq!(p["items"][0]["subject"],"café");assert_eq!(merge(&json!({}),&p).unwrap()["items"].as_array().unwrap().len(),1);assert!(p["items"][0].get("htmlBody").is_none());}
#[test]fn email_bad_account_missing_and_duplicate_results_fail(){let original:Value=serde_json::from_str(r()["text"].as_str().unwrap()).unwrap();for (path,value)in [(0,json!("wrong")),(1,json!(["missing"]))]{let mut v=original.clone();if path==0{v["methodResponses"][1][1]["accountId"]=value}else{v["methodResponses"][1][1]["notFound"]=value}assert!(page(&m(),&json!({"status":200,"text":v.to_string()}),0).is_err());}assert!(page(&m(),&json!({"status":401}),0).is_err());}
#[test]fn email_pagination_rejects_binding_state_and_gap_without_mutating_snapshot(){let old=page(&m(),&r(),0).unwrap();let saved=old.clone();let mut next=old.clone();next["position"]=json!(20);next["query_state"]=json!("q2");assert!(merge(&old,&next).is_err());next["query_state"]=json!("q1");assert!(merge(&old,&next).is_err());assert_eq!(old,saved);}
}
